mapper.insert:
INSERT INTO gifticon_products (
    name, brand_name, category, face_value_krw, required_points,
    status, image_url, created_at, updated_at
) VALUES (
    #{name}, #{brandName}, #{category}, #{faceValueKrw}, #{requiredPoints},
    #{status}, #{imageUrl,jdbcType=VARCHAR}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT p.gifticon_product_id, p.name, p.brand_name, p.category, p.face_value_krw, p.required_points, p.status, p.image_url, p.created_at, p.updated_at, COALESCE(SUM(CASE WHEN c.status = 'AVAILABLE' AND c.expires_at > UTC_TIMESTAMP() THEN 1 ELSE 0 END), 0) AS available_code_count, COALESCE(SUM(CASE WHEN c.status = 'ASSIGNED' THEN 1 ELSE 0 END), 0) AS assigned_code_count, COALESCE(SUM(CASE WHEN c.status = 'VOID' THEN 1 ELSE 0 END), 0) AS void_code_count FROM gifticon_products p LEFT JOIN gifticon_codes c ON c.gifticon_product_id = p.gifticon_product_id
AND p.status = #{status} AND p.gifticon_product_id > #{cursor}
GROUP BY p.gifticon_product_id, p.name, p.brand_name, p.category, p.face_value_krw, p.required_points, p.status, p.image_url, p.created_at, p.updated_at ORDER BY p.gifticon_product_id LIMIT #{size}
